const fs=require('fs'),path=require('path');
const sharp=require('C:/Users/Evan Robinson/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/sharp');
(async()=>{const m=JSON.parse(fs.readFileSync(path.join(__dirname,'manifest.json'))),layers=[];for(let i=0;i<m.characters.length;i++){let s=fs.readFileSync(path.join(__dirname,m.characters[i].src),'utf8').replace(/var\(--[\w-]+,([^\)]+)\)/g,'$1');layers.push({input:await sharp(Buffer.from(s)).resize(224,256).png().toBuffer(),left:40+(i%4)*260,top:40+Math.floor(i/4)*310});for(const [j,n]of [24,40,64].entries())layers.push({input:await sharp(Buffer.from(s)).resize(Math.round(n*112/128),n).png().toBuffer(),left:90+(i%4)*260+j*48,top:320+Math.floor(i/4)*310-n})}await sharp({create:{width:1120,height:680,channels:4,background:'#f7f3e7'}}).composite(layers).png().toFile(path.join(__dirname,'character-proof.png'))})();
